        let slotDef = OrganEffectSlotDefinition[i]
        paintObj[slotDef.id] = {
            'x': slotDef.x,
            'y': slotDef.y,
            'item': effect.item.id,
            'overlay': effect.overlay,
            'customText': effect.customText,
            'visible': effect.visible
        }
